        retention: 7,
      },
      weekly: {
        enabled: true,
        type: 'RDB + AOF',
        day: 'Sunday',
        time: '03:00',
        retention: 4,
      },
      monthly: {
        enabled: true,
        type: 'RDB + AOF',
        day: 1,
        time: '04:00',
