  }

  async calculateDailySalesTrend(
    days = 30
  ): Promise<any[]> {
    const endDate = Date.now();
    const startDate = endDate - days * 24 * 60 * 60 * 1000;

    const query = `@createdAt:[${startDate} ${endDate}]`;

    const result = await (this.redis as any).call(
